    /**
     * Tests getting all AppliedFees.
     *
     * @return    Collection
     */
    public List<AppliedFee> testGetAll() throws Throwable {
    LOGGER.info( "AppliedFeeTest:testGetAll() - Retrieving Collection of AppliedFees:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all AppliedFee : " );
    List<AppliedFee> collection  = null;

    try {
        // call the static get method on the AppliedFeeService
        collection = service.getAllAppliedFee();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            AppliedFee currEntity  = null;
            Iterator<AppliedFee> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAppliedFeeId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

